import {bounds,plain,edgePoints} from './model.js';
import {drawMath} from './math.js';
export function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
export function exportProject(p){download(new Blob([JSON.stringify({format:'lousa',...p})],{type:'application/json'}),`${p.name}.lousa.json`)}
function rounded(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function wrap(ctx,text,width){return text.split('\n').flatMap(line=>{const out=[];let s='';for(const word of line.split(' ')){if(s&&ctx.measureText(s+' '+word).width>width){out.push(s);s=word}else s+=(s?' ':'')+word}out.push(s);return out})}
function drawRich(ctx,n,pad){
 const root=document.createElement('div');root.innerHTML=n.html;
 const maxWidth=n.w-pad*2,lines=[];let line={parts:[],width:0,height:n.fontSize*1.5,align:n.align};
 const font=s=>`${s.italic?'italic ':''}${s.bold?'700 ':''}${s.size}px ${s.family}`;
 const newline=(align=line.align)=>{lines.push(line);line={parts:[],width:0,height:n.fontSize*1.5,align}};
 const put=(txt,s)=>{for(const t of txt.split(/(\n|[ \t]+)/)){if(!t)continue;if(t==='\n'){newline(s.align);continue}ctx.font=font(s);let pieces=[t];if(ctx.measureText(t).width>maxWidth){pieces=[...t]}for(const word of pieces){const w=ctx.measureText(word).width;if(line.width+w>maxWidth&&line.parts.length)newline(s.align);line.parts.push({text:word,w,s});line.width+=w;line.height=Math.max(line.height,s.size*1.5);line.align=s.align}}};
 const walk=(el,style,depth=0)=>{if(depth>80)return;if(el.nodeType===3){put(el.textContent,style);return}if(el.nodeType!==1)return;const s={...style},tag=el.tagName,css=el.style;
 if(['B','STRONG'].includes(tag))s.bold=true;if(['I','EM'].includes(tag))s.italic=true;if(tag==='U')s.underline=true;if(tag==='MARK')s.bg='#fff2a6';
 if(css.color)s.color=css.color;if(css.backgroundColor)s.bg=css.backgroundColor;if(css.fontFamily)s.family=css.fontFamily;if(css.fontWeight)s.bold=css.fontWeight==='bold'||+css.fontWeight>=600;if(css.fontStyle)s.italic=css.fontStyle==='italic';if(css.textAlign)s.align=css.textAlign;if(css.textDecoration?.includes('underline'))s.underline=true;
 if(css.fontSize){const z=parseFloat(css.fontSize);if(Number.isFinite(z))s.size=Math.min(300,Math.max(6,css.fontSize.endsWith('em')?z*style.size:z))}if(tag==='FONT'){if(el.getAttribute('color'))s.color=el.getAttribute('color');if(el.getAttribute('face'))s.family=el.getAttribute('face');if(el.getAttribute('size'))s.size=[0,10,13,16,18,24,32,48][+el.getAttribute('size')]||style.size}
 if(tag==='BR'){newline(s.align);return}const block=['DIV','P','H1','H2','H3','LI','PRE'].includes(tag);if(block&&line.parts.length)newline(s.align);if(tag==='LI'){const siblings=[...el.parentElement.children],ordered=el.parentElement.tagName==='OL';put(ordered?`${siblings.indexOf(el)+1}. `:'• ',s)}
 for(const child of el.childNodes)walk(child,s,depth+1);if(block&&line.parts.length)newline(s.align)};
 const base={size:n.fontSize,family:n.fontFamily,color:n.color,bold:n.bold,italic:false,underline:false,align:n.align,bg:null};for(const child of root.childNodes)walk(child,base);if(line.parts.length||!lines.length)lines.push(line);let y=Math.max(pad,(n.h-lines.reduce((a,l)=>a+l.height,0))/2);ctx.textAlign='left';for(const l of lines){let x=l.align==='center'?(n.w-l.width)/2:l.align==='right'?n.w-pad-l.width:pad;for(const p of l.parts){ctx.font=font(p.s);if(p.s.bg){ctx.fillStyle=p.s.bg;ctx.fillRect(x,y,p.w,l.height)}ctx.fillStyle=p.s.color;ctx.fillText(p.text,x,y+l.height*.75);if(p.s.underline){ctx.strokeStyle=p.s.color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y+l.height*.8);ctx.lineTo(x+p.w,y+l.height*.8);ctx.stroke()}x+=p.w}y+=l.height}
}
export async function renderImage(b,selected=[],dark=false){let ns=b.nodes.filter(n=>!n.hidden),ss=b.strokes;if(selected.length){ns=ns.filter(n=>selected.includes(n.id));ss=[]}const area=bounds(ns,ss),pad=45;area.x-=pad;area.y-=pad;area.w+=pad*2;area.h+=pad*2;const scale=Math.min(2,8192/area.w,8192/area.h,Math.sqrt(24e6/(area.w*area.h)));const c=document.createElement('canvas');c.width=Math.ceil(area.w*scale);c.height=Math.ceil(area.h*scale);const ctx=c.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle=dark?'#201f28':'#faf9f6';ctx.fillRect(0,0,area.w,area.h);ctx.translate(-area.x,-area.y);const nodeMap=new Map(ns.map(n=>[n.id,n]));for(const e of b.edges){const a=nodeMap.get(e.from),n=nodeMap.get(e.to);if(!a||!n)continue;const[p,q]=edgePoints(a,n);ctx.strokeStyle=e.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.bezierCurveTo(p.x+(q.x-p.x)/2,p.y,q.x-(q.x-p.x)/2,q.y,q.x,q.y);ctx.stroke();if(e.arrow){ctx.fillStyle=e.color;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x-Math.sign(q.x-p.x||1)*10,q.y-5);ctx.lineTo(q.x-Math.sign(q.x-p.x||1)*10,q.y+5);ctx.fill()}if(e.label){ctx.font='13px Arial';ctx.fillStyle=dark?'#c5b9d1':'#72627e';ctx.textAlign='center';ctx.fillText(e.label,(p.x+q.x)/2,(p.y+q.y)/2-9)}}
for(const s of ss){if(!s.points.length)continue;ctx.strokeStyle=s.color;ctx.globalAlpha=s.highlight?.35:1;ctx.lineWidth=s.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.globalAlpha=1}
for(const original of ns){const n={...original,color:dark&&original.fill==='transparent'&&original.color==='#302741'?'#efedf5':original.color};ctx.save();ctx.translate(n.x,n.y);if(n.fill!=='transparent'){ctx.fillStyle=n.fill;if(n.shape==='ellipse'){ctx.beginPath();ctx.ellipse(n.w/2,n.h/2,n.w/2,n.h/2,0,0,Math.PI*2);ctx.fill()}else if(n.shape==='diamond'){ctx.beginPath();ctx.moveTo(n.w/2,0);ctx.lineTo(n.w,n.h/2);ctx.lineTo(n.w/2,n.h);ctx.lineTo(0,n.h/2);ctx.fill()}else rounded(ctx,0,0,n.w,n.h,n.type==='note'?2:12)}ctx.beginPath();ctx.rect(0,0,n.w,n.h);ctx.clip();if(n.type==='image'){try{const im=new Image();im.src=n.src;await im.decode();const r=Math.max(n.w/im.width,n.h/im.height),w=im.width*r,h=im.height*r;ctx.drawImage(im,(n.w-w)/2,(n.h-h)/2,w,h)}catch{ctx.fillStyle='#888';ctx.fillText('[Imagem indisponível]',10,30)}}else if(n.type==='formula'){drawMath(ctx,n.text,3,Math.max(10,(n.h-n.fontSize*1.5)/2),n.fontSize,n.color)}else if(n.html){drawRich(ctx,n,n.type==='text'?0:22)}else{const pad=n.type==='text'?0:22;const txt=n.type==='audio'?'♫ '+n.text:plain(n.html)||n.text;const fs=n.type==='audio'?16:n.fontSize;ctx.font=`${n.bold?'700 ':''}${fs}px ${n.type==='code'?'Consolas':n.fontFamily||'Arial'}`;ctx.fillStyle=n.color;ctx.textAlign=n.align||'left';const lines=n.type==='code'?txt.split('\n'):wrap(ctx,txt,n.w-pad*2);const lh=fs*1.5;const y=Math.max(pad,(n.h-lines.length*lh)/2);lines.forEach((s,i)=>ctx.fillText(s,n.align==='center'?n.w/2:n.align==='right'?n.w-pad:pad,y+(i+.8)*lh))}ctx.restore()}return c}
export function canvasBlob(c,type='image/png',quality=.95){return new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(Error('Não foi possível gerar a imagem.')),type,quality))}
export async function exportPNG(b,sel,dark){const c=await renderImage(b,sel,dark);download(await canvasBlob(c),b.name+'.png')}
export function createPDF(jpeg,width,height){const enc=new TextEncoder(),parts=[],offsets=[0];let size=0;const add=s=>{const a=typeof s==='string'?enc.encode(s):s;parts.push(a);size+=a.length};const obj=(id,s)=>{offsets[id]=size;add(`${id} 0 obj\n${s}\nendobj\n`)};const w=960,h=w*height/width;add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=size;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);add(jpeg);add('\nendstream\nendobj\n');const content=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ`;obj(5,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`);const xref=size;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
export async function exportPDF(b,sel,dark){const c=await renderImage(b,sel,dark),jpeg=new Uint8Array(await(await canvasBlob(c,'image/jpeg')).arrayBuffer());download(createPDF(jpeg,c.width,c.height),b.name+'.pdf')}
